// The Breakthrough 2027 banner, as a data URI.
//
// Embedded rather than fetched: the delivery picture is drawn on a canvas in
// the browser and turned straight into a JPEG, and an <img> that has not
// finished loading draws as nothing at all. A banner that is sometimes there
// is worse than one that always is.
export const BREAKTHROUGH = "data:image/jpeg;base64,";
